head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
// 문자열 길이 체크
scwin.getPar, scwin.setPar;
scwin.dts_Recv;
scwin.TR_JOB;
scwin.fr_SecuGrpId;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.VListBzTpCd = LIST_BZ_TP_CD_122;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // var parentWin = fn_GetProvider();
        const parentWin = $c.frame.path("../");
        // alert('[parentWin]'+parentWin);
        scwin.dts_Recv = parentWin.scwin.dts_Recv;
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vAcptNo = parentWin.scwin.vAcptNo;
        scwin.vIsurCd = parentWin.txb_ISUR_CD.getValue();
        scwin.fr_SecuGrpId = parentWin.pSecuGrpId;
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = parentWin.scwin.vSPOT_ISU_TRD_MKT_TP_CD;
        scwin.vOpenTyp = parentWin.scwin.vOpenTyp;
        edt_APPROV_DD.setValue($c.ut.cGetToday("yyyymmdd"));
        $c.libRoundPanel.PanelToGroupBox(panel_Item);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성s
        // buttonSet.setDrftInfo( btn_Drft, fn_drft );            // 기안

        if (scwin.vOpenTyp === "R") {
            await scwin.setHeader();
            scwin.recvReadSync(scwin.dts_Recv.getFocusedRowIndex());
            buttonSet.setInsertStatus();
        } else if (scwin.vOpenTyp === "H") {
            await scwin.readSync();
        } else if (scwin.vOpenTyp === "N") {
            await scwin.setHeader();
            scwin.initItem();
            buttonSet.setInsertStatus();
            scwin.setBtnRecvIsuDel();
        }

        // 코스닥일때 보임
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "1") {
            btn_Print.hide();
            label_1.hide();
            edt_APPROV_DD.hide();
            img_APPROV_DD.hide();
        } else {
            if (scwin.vOpenTyp === "R" && scwin.vBzProcsNo !== "") {
                btn_Print.hide();
                label_1.hide();
                edt_APPROV_DD.hide();
                img_APPROV_DD.hide();
            } else {
                btn_Print.show("");
                label_1.show("");
                edt_APPROV_DD.show("");
                img_APPROV_DD.show("");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05801.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_ISU_CD_onclick
 * @description img_ISU_CD 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ISU_CD_onclick = async function() {
    try {
        if (scwin.vIsurCd === "") {
            await $c.win.alert("[회사]를 선택하세요.");
            return;
        }
        scwin.getPar = scwin.getParIsuCd;
        scwin.setPar = scwin.setParIsuCd;
        $c.lc.fn_PopFindNewIsuOfIsur();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05801.img_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05801.btn_Close_onclick" });
    }
};

