///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Isu.insertRow();
    // alert(dts_Isu.text+" dts_Isu.text");

};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05801.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_NEW_ISS_SWR_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_Isu.getCellData(1, "NPARVALSTK_YN") === 'Y') {
        chk_NPARVALSTK_YN.setValue(1);
    }
    const sbmOptions2 = {
        id : "sbm_dts_Eng_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Eng_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    if (scwin.TR_JOB === 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    // alert("[fn_trs vBzProcsNo] ."+vBzProcsNo);
    // dts_Isu.NameValue(1, "JOB_TYPE") = trsIdx;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    dts_Isu.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_Isu.setCellData(1, "LIST_BZ_TP_CD", scwin.VListBzTpCd); /*ORG SRC: dts_Isu.NameString(1, "NPARVALSTK_YN") = (fn_getCheckboxData(chk_NPARVALSTK_YN) == "Y" ? "Y" : '');*/ X = (scwin.getCheckboxData(chk_NPARVALSTK_YN) === "Y" ? "Y" : '');
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsIdx,
    //     ACPT_NO : scwin.vAcptNo,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     COUNT : "1",
    //     LIST_BZ_TP_CD : scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_NEW_ISS_SWR_HIST
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/Listing.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/* =============================== */
/*       인쇄버튼 추가 2010.01.21        */

