    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsuCd
 * @description 신주인수권증서 신주상장
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.fr_SecuGrpId;
    arrPar[1] = scwin.vIsurCd; // 코드값을 포함할 컨트롤
    arrPar[2] = "S";
    // alert('fr_SecuGrpId'+fr_SecuGrpId);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsuCd
 * @description set Par Isu Cd 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsuCd = function(arrPar) {
    if (arrPar[0].ISU_CD !== "") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_KOR_NM.setValue(arrPar[0].ISU_KOR_NM);
        txb_ISU_KOR_ABBRV.setValue(arrPar[0].ISU_KOR_ABBRV);
        txb_ISU_ENG_NM.setValue(arrPar[0].ISU_ENG_NM);
        txb_ISU_ENG_ABBRV.setValue(arrPar[0].ISU_ENG_ABBRV);
        txb_ISU_SRT_CD.setValue(arrPar[0].ISU_SRT_CD);
        edt_ISU_RND.setValue(arrPar[0].ISU_RND);
        edt_ISU_DD.setValue(arrPar[0].ISU_DD);
        txb_TARSTK_ISU_NM.setValue(arrPar[0].TARSTK_ISU_NM);
        dts_Isu.setCellData(1, "TARSTK_ISU_CD", arrPar[0].TARSTK_ISU_CD);
        // dts_Isu.NameString(1, "ISU_ENG_SYMBL") = '-'; ///////////test

    }
};

/**
 * @method
 * @name initItem
 * @description init Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.initItem = function() {
    cmb_LIST_METHD_TP_CD.setValue(LIST_METHD_TP_CD_1);
};

/**
 * @method
 * @name recvReadSync
 * @description recv Read Sync 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.recvReadSync = function(row) {
    dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.dts_Recv.getCellData(row, "BZ_PROCS_NO"));
    dts_Isu.setCellData(1, "ACPT_NO", scwin.dts_Recv.getCellData(row, "ACPT_NO"));
    // dts_Isu.NameString(1, "LIST_METHD_TP_CD") = LIST_METHD_TP_CD_1
    dts_Isu.setCellData(1, "DELIST_DD", scwin.dts_Recv.getCellData(row, "DELIST_DD"));
    dts_Isu.setCellData(1, "ISU_DD", scwin.dts_Recv.getCellData(row, "ISU_DD"));
    dts_Isu.setCellData(1, "LIST_SHRS", scwin.dts_Recv.getCellData(row, "RGHT_CNT"));
    dts_Isu.setCellData(1, "NPARVALSTK_YN", scwin.dts_Recv.getCellData(row, "NPARVALSTK_YN"));
    dts_Isu.setCellData(1, "EXER_PRC", scwin.dts_Recv.getCellData(row, "EXER_PRC"));
    dts_Isu.setCellData(1, "EXER_PRC", scwin.dts_Recv.getCellData(row, "EXER_PRC"));
    dts_Isu.setCellData(1, "TOT_ISU_PRC", scwin.dts_Recv.getCellData(row, "TOT_PAR"));
    dts_Isu.setCellData(1, "EXER_STRT_DD", scwin.dts_Recv.getCellData(row, "EXER_STRT_DD"));
    dts_Isu.setCellData(1, "EXER_END_DD", scwin.dts_Recv.getCellData(row, "EXER_END_DD"));
    dts_Isu.setCellData(1, "REMK", scwin.dts_Recv.getCellData(row, "REMK"));
    if (dts_Isu.getCellData(1, "NPARVALSTK_YN") === 'Y') {
        chk_NPARVALSTK_YN.setValue(1);
    } else {
        chk_NPARVALSTK_YN.setValue(0);
    }
    scwin.initItem();
};

/**
 * @method
 * @name checkValueNullMaxlength
 * @description 한글포함된 문자열 널값 및 최대길이 확인
 * @param {*} vObj vObj
 * @param {*} vTitle vTitle
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValueNullMaxlength = async function(vObj, vTitle) {
    const vMaxLength = vObj.maxLength;
    if (vObj.getValue() === "") {
        await $c.win.alert(vTitle + "을 입력하세요.");
        vObj.focus();
        return false;
    }
    if ($c.str.getByteLength(vObj) > vMaxLength) {
        await $c.win.alert("[" + vTitle + "] 입력길이가 " + vMaxLength + "Byte를 초과할 수 없습니다.(한글 : 2 byte 숫자,영문 : 1byte)");
        vObj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if (scwin.TR_JOB === 'I') {
        if ($c.pre_newlisting.fn_checkDoubleInput(dts_DoubleChk, txb_ISU_CD.getValue())) return false;
    }
    if (!await scwin.checkValueNullMaxlength(txb_ISU_KOR_NM, "한글종목명")) return false;
    if (!await scwin.checkValueNullMaxlength(txb_ISU_KOR_ABBRV, "한글종목약명")) return false;
    if (!await scwin.checkValueNullMaxlength(txb_ISU_ENG_NM, "영문종목명")) return false;
    if (!await scwin.checkValueNullMaxlength(txb_ISU_ENG_ABBRV, "영문종목약명")) return false;
    if (txb_ISU_SRT_CD.getValue() === "") {
        await $c.win.alert("[종목단축코드]항목값이  없습니다."); // txb_ISU_SRT_CD.focus();return false;

    }
    if (txb_ISU_KOR_NM.getValue() === "") {
        await $c.win.alert("[한글종목명]을 입력하세요.");
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if (txb_ISU_KOR_ABBRV.getValue() === "") {
        await $c.win.alert("[한글종목약명]을 입력하세요.");
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ENG_NM.getValue() === "") {
        await $c.win.alert("[영문종목명]을 입력하세요.");
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() === "") {
        await $c.win.alert("[영문종목약명]을 입력하세요.");
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (edt_ISU_DD.getValue() === "") {
        await $c.win.alert("[발행일]을 입력하세요.");
        edt_ISU_DD.focus();
        return false;
    }
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= edt_LIST_DD.getValue()) {
        await $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[상장폐지일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= edt_DELIST_DD.getValue()) {
        await $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if (parseInt(edt_LIST_DD.getValue(), 10) >= parseInt(edt_DELIST_DD.getValue(), 10)) {
        await $c.win.alert("[상장일]은 [상장폐지일]보다 작아야 합니다. 다시 입력해주세요");
        return false;
    }
    if (edt_EXER_STRT_DD.getValue() === "") {
        await $c.win.alert("[목적주권 청약시작일]을 입력하세요.");
        edt_EXER_STRT_DD.focus();
        return false;
    }
    if (edt_EXER_END_DD.getValue() === "") {
        await $c.win.alert("[목적주권 청약종료일]을 입력하세요.");
        edt_EXER_END_DD.focus();
        return false;
    }
    if (parseInt(edt_EXER_STRT_DD.getValue(), 10) >= parseInt(edt_EXER_END_DD.getValue(), 10)) {
        await $c.win.alert("[청약시작일]은 [청약종료일]보다 작아야 합니다. 다시 입력해주세요");
        return false;
    }
    if (cmb_LIST_METHD_TP_CD.getValue() === "") {
        await $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if (edt_LIST_SHRS.getValue() === "") {
        await $c.win.alert("[상장증서수량]을 입력하세요.");
        edt_LIST_SHRS.focus();
        return false;
    }
    // if (! fn_checkNumber(edt_LIST_SHRS, '상장증서수량')) return false;

    if (edt_EXER_PRC.getValue() === "") {
        await $c.win.alert("[목적주권의 발행가격]을 입력하세요.");
        edt_EXER_PRC.focus();
        return false;
    }
    // if (! fn_checkNumber(edt_EXER_PRC, '목적주권의 발행가격')) return false;

    if (txb_ISU_RSN_CONTN.getValue() === "") {
        await $c.win.alert("[발행사유]를 입력하세요.");
        txb_ISU_RSN_CONTN.focus();
        return false;
    }

    /* 2009-04-24  신주인수권증서 신주상장 중복입력체크 */
    ///*
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, txb_ISU_CD.getValue(), edt_LIST_DD.getValue(), scwin.vBzProcsNo, LIST_BZ_TP_CD_122)) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkNumber
 * @description check Number 처리
 * @param {Object} obj 컴포넌트
 * @param {String} str str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkNumber = async function(obj, str) {
    if (obj.getValue() <= 100) {
        await $c.win.alert("[" + str + "]를 '" + obj.getValue() + "'으로 입력하셨습니다. 확인 후 재입력바랍니다.");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vAcptNo === "") {
            scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            // dts_Isu.UserStatus(1) = TB_JOB_INSERT;
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            await scwin.trs(TRS_IDX_INSERT);
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TRS_IDX_UPDATE);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    await scwin.trs(TRS_IDX_DELETE);
};

/**
 * @method
 * @name recvtIsuDel
 * @description recvt Isu Del 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvtIsuDel = async function() {
    if (scwin.vAcptNo === "") {
        await $c.win.alert('발행예정내역에서 대상종목을 선택하세요');
        return;
    }
    await scwin.delete();
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }

    // if (  dts_Isu.IsUpdated  ) {
    //    alert(getMessageParam("MSG-0022", ""));
    //    return ;
    // }

    let OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "1") {
        // 유가경우
        scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            arr[0] = "68915";
            arr[1] = scwin.vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            // CopyDataSet( dts_Delistdetail , param_dts_isu) ;
            $c.stf.copyDataSet(dts_Isu, param_dts_mst);
            return arr.length;
        };
    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "2") {
        // 코스닥인경우
        scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
            arr[0] = "70926";
            arr[1] = scwin.vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
            $c.stf.copyDataSet(dts_Isu, param_dts_mst);
            $c.stf.copyDataSet(dts_Eng_Isu, param_dts_mst_eng);
            return arr.length;
        };
    }
    scwin.setPar = function(arr) {

    };
    const wth = 750;
    const hgt = 820;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

/**
 * @method
